#[summary("tasks")]
mod tasks {
    spec fn is_floor_mid(a: i64, b: i64, r: i64) -> bool {
        2 * r <= a + b && a + b < 2 * r + 2
    }

    #[effects(pure)]
    #[uses(is_floor_mid)]
    fn midpoint(a: i64, b: i64) -> (r: i64)
        ensures is_floor_mid(a, b, r),
    {
        let ha: i64 = a / 2;
        let hb: i64 = b / 2;
        let fa: i64 = if a % 2 < 0 {
            ha - 1
        } else {
            ha
        };
        let fb: i64 = if b % 2 < 0 {
            hb - 1
        } else {
            hb
        };
        let ra: i64 = a - 2 * fa;
        let rb: i64 = b - 2 * fb;
        fa + fb + (ra + rb) / 2
    }
}

#[summary("saturating sum")]
mod tasks {
    spec fn inv(a: &[i64], i: usize, acc: i64) -> bool {
        i <= a.len() && acc == sat_prefix(a, i)
    }

    spec fn is_sat_sum(a: &[i64], r: i64) -> bool {
        r == sat_prefix(a, a.len())
    }

    spec fn sat_add(x: i64, y: i64) -> i64 {
        if x + y > 9223372036854775807 {
            9223372036854775807
        } else if x + y < -9223372036854775808 {
            -9223372036854775808
        } else {
            x + y
        }
    }

    spec fn sat_prefix(a: &[i64], n: usize) -> i64
        decreases n,
    {
        if n == 0 {
            0
        } else if n > a.len() {
            0
        } else {
            sat_add(sat_prefix(a, n - 1), a[n - 1])
        }
    }

    #[effects(pure)]
    #[uses(inv, is_sat_sum, sat_add, sat_prefix)]
    fn sat_sum(a: &[i64]) -> (r: i64)
        ensures is_sat_sum(a, r),
    {
        let mut acc: i64 = 0;
        let mut i: usize = 0;
        while i < a.len()
            invariant inv(a, i, acc),
            decreases a.len() - i,
        {
            let x: i64 = a[i];
            if x > 0 && acc > 9223372036854775807 - x {
                acc = 9223372036854775807;
            } else if x < 0 && acc < -9223372036854775807 - 1 - x {
                acc = -9223372036854775807 - 1;
            } else {
                acc = acc + x;
            }
            i = i + 1;
        }
        acc
    }
}

#[summary("count elements within inclusive range")]
mod tasks {
    #[effects(pure)]
    #[uses(full_cnt, inv, is_cnt)]
    fn count_in_range(a: &[i64], lo: i64, hi: i64) -> (r: usize)
        ensures full_cnt(a, lo, hi, r),
    {
        let mut i: usize = 0;
        let mut c: usize = 0;
        while i < a.len()
            invariant inv(a, lo, hi, i, c),
            decreases a.len() - i,
        {
            if lo <= a[i] && a[i] <= hi {
                c = c + 1;
            }
            i = i + 1;
        }
        c
    }

    spec fn full_cnt(a: &[i64], lo: i64, hi: i64, r: usize) -> bool {
        is_cnt(a, lo, hi, a.len(), r)
    }

    spec fn inv(a: &[i64], lo: i64, hi: i64, i: usize, c: usize) -> bool {
        i <= a.len() && c <= i && is_cnt(a, lo, hi, i, c)
    }

    spec fn is_cnt(a: &[i64], lo: i64, hi: i64, n: usize, r: usize) -> bool
        decreases n,
    {
        if n == 0 {
            r == 0
        } else if lo <= a[n - 1] && a[n - 1] <= hi {
            r >= 1 && is_cnt(a, lo, hi, n - 1, r - 1)
        } else {
            is_cnt(a, lo, hi, n - 1, r)
        }
    }
}

