        requires nonempty(a),
        ensures is_first_max(a, r),
    {
        let mut i: usize = 1;
        let mut b: usize = 0;
        while i < a.len()
            invariant scan_inv(a, i, b),
            decreases a.len() - i,
        {
            if a[i] > a[b] {
                b = i;
            }
            i = i + 1;
        }
        b
    }

    spec fn is_first_max(a: &[i64], r: usize) -> bool {
        r < a.len() && (forall|j: usize| j < a.len() ==> #[trigger] a[j] <= a[r]) && (forall|k: usize| k < r ==> #[trigger] a[k] < a[r])
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }

    spec fn scan_inv(a: &[i64], i: usize, b: usize) -> bool {
