#[summary("slice tasks")]
mod tasks {
    spec fn inv(a: &[i64], i: usize) -> bool {
        i <= a.len() && pre(a, i + 1)
    }

    spec fn pre(a: &[i64], k: usize) -> bool {
        forall|j: usize| j + 1 < k && j + 1 < a.len() ==> #[trigger] a[j] < a[j + 1]
    }

    spec fn res(a: &[i64], r: bool) -> bool {
        r == pre(a, a.len())
    }

    #[effects(pure)]
    #[uses(inv, pre, res)]
    fn strictly_increasing(a: &[i64]) -> (r: bool)
        ensures res(a, r),
    {
        let mut i: usize = 0;
        while i + 1 < a.len() && a[i] < a[i + 1]
            invariant inv(a, i),
            decreases a.len() - i,
        {
            i = i + 1;
        }
        i + 1 >= a.len()
    }
}

#[summary("binary search tasks")]
mod tasks {
    spec fn below(a: &[i64], t: i64, lo: usize) -> bool {
        forall|k: usize| k < lo && k < a.len() ==> #[trigger] a[k] < t
    }

    spec fn bound_ok(a: &[i64], t: i64, hi: usize) -> bool {
        hi <= a.len() && (hi == a.len() || a[hi] >= t)
    }

    spec fn bracket(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }

    #[effects(pure)]
    #[uses(below, bound_ok, bracket, result_ok, sorted)]
    fn lower_bound(a: &[i64], t: i64) -> (r: usize)
        requires sorted(a),
        ensures result_ok(a, t, r),
    {
        let mut lo: usize = 0;
        let mut hi: usize = a.len();
        while lo < hi
            invariant bracket(a, lo, hi), below(a, t, lo), bound_ok(a, t, hi), sorted(a),
            decreases hi - lo,
        {
            let mid: usize = lo + (hi - lo) / 2;
            if a[mid] < t {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        hi
    }

    spec fn result_ok(a: &[i64], t: i64, r: usize) -> bool {
        r <= a.len() && below(a, t, r) && bound_ok(a, t, r)
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i <= j && j < a.len() ==> #[trigger] a[i] <= #[trigger] a[j]
    }
}

