    fn div_floor(a: i64, b: i64) -> (r: i64)
        requires dom(a, b),
        ensures is_floor(a, b, r),
    {
        let q: i64 = a / b;
        let m: i64 = a % b;
        if m != 0 && (m < 0) != (b < 0) {
            q - 1
        } else {
            q
        }
    }

    spec fn dom(a: i64, b: i64) -> bool {
        b != 0 && !(a == -9223372036854775808 && b == -1)
    }

    spec fn is_floor(a: i64, b: i64, r: i64) -> bool {
        if b > 0 {
            r * b <= a && a - r * b < b
        } else {
            r * b >= a && a - r * b > b
        }
    }
}

