#[summary("Maximum subarray sum (Kadane)")]
mod tasks {
    spec fn best_ok(a: &[i64], k: usize, bi: usize, bj: usize, c: i64) -> bool {
        bi < bj && bj <= k && rsum(a, bi, bj) == c && (forall|u: usize, v: usize| u < v && v <= k ==> #[trigger] rsum(a, u, v) <= c)
    }

    spec fn best_upto(a: &[i64], k: usize, c: i64) -> bool {
        (exists|q: usize, s: usize| q < s && s <= k && #[trigger] rsum(a, q, s) == c) && (forall|u: usize, v: usize| u < v && v <= k ==> #[trigger] rsum(a, u, v) <= c)
    }

    spec fn bounded(k: usize, c: i64) -> bool {
        -1000000000 <= c && c <= 1000000000 * k
    }

    spec fn ends_ok(a: &[i64], k: usize, s: usize, c: i64) -> bool {
        s < k && rsum(a, s, k) == c && (forall|r: usize| r < k ==> #[trigger] rsum(a, r, k) <= c)
    }

    spec fn in_dom(a: &[i64]) -> bool {
        a.len() >= 1 && a.len() <= 1000000 && (forall|p: usize| p < a.len() ==> -1000000000 <= #[trigger] a[p] && a[p] <= 1000000000)
    }

    #[effects(pure)]
    #[uses(best_ok, best_upto, bounded, ends_ok, in_dom, rsum)]
    fn max_subarray(a: &[i64]) -> (r: i64)
        requires in_dom(a),
        ensures best_upto(a, a.len(), r),
    {
        let mut cur: i64 = a[0];
        let mut best: i64 = a[0];
        let mut cs: usize = 0;
        let mut bi: usize = 0;
        let mut bj: usize = 1;
        let mut k: usize = 1;
        while k < a.len()
            invariant in_dom(a), 1 <= k, k <= a.len(), ends_ok(a, k, cs, cur), best_ok(a, k, bi, bj, best), bounded(k, cur), bounded(k, best),
            decreases a.len() - k,
        {
            if cur > 0 {
                cur = cur + a[k];
            } else {
                cur = a[k];
                cs = k;
            }
            if cur > best {
                best = cur;
                bi = cs;
                bj = k + 1;
            }
            k = k + 1;
        }
        best
    }

    spec fn rsum(a: &[i64], i: usize, j: usize) -> i64
        decreases j,
    {
        if j <= i {
            0
        } else {
            rsum(a, i, j - 1) + a[j - 1]
        }
    }
}

#[summary("second_max task")]
mod tasks {
    spec fn all_equal(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i < a.len() && j < a.len() ==> #[trigger] a[i] == #[trigger] a[j]
    }

    spec fn full_max(a: &[i64], m: i64) -> bool {
        (exists|j: usize| j < a.len() && #[trigger] a[j] == m) && (forall|k: usize| k < a.len() ==> #[trigger] a[k] <= m)
    }

    spec fn is_second(a: &[i64], r: i64) -> bool {
        exists|j: usize| j < a.len() && #[trigger] a[j] > r && (forall|k: usize| k < a.len() ==> #[trigger] a[k] <= a[j]) && (exists|i: usize| i < a.len() && #[trigger] a[i] == r) && (forall|q: usize| q < a.len() ==> a[q] == a[j] || #[trigger] a[q] <= r)
    }

    spec fn max_inv(a: &[i64], m: i64, i: usize) -> bool {
        i <= a.len() && (exists|j: usize| j < i && #[trigger] a[j] == m) && (forall|k: usize| k < i ==> #[trigger] a[k] <= m)
    }

    spec fn result_ok(a: &[i64], r: i64) -> bool {
        if all_equal(a) {
            r == i64::MIN
        } else {
            is_second(a, r)
        }
    }

    spec fn sec_inv(a: &[i64], m: i64, s: i64, found: bool, i: usize) -> bool {
        i <= a.len() && (forall|k: usize| k < i ==> a[k] == m || #[trigger] a[k] <= s) && (found ==> s < m && (exists|j: usize| j < i && #[trigger] a[j] == s)) && (!found ==> s == i64::MIN && (forall|q: usize| q < i ==> #[trigger] a[q] == m))
    }

    #[effects(pure)]
    #[uses(all_equal, full_max, is_second, max_inv, result_ok, sec_inv)]
    fn second_max(a: &[i64]) -> (r: i64)
        ensures result_ok(a, r),
    {
        if a.len() == 0 {
            i64::MIN
        } else {
            let mut m: i64 = a[0];
            let mut i: usize = 1;
            while i < a.len()
                invariant max_inv(a, m, i), 1 <= i,
                decreases a.len() - i,
            {
                if a[i] > m {
                    m = a[i];
                }
                i = i + 1;
            }
            let mut s: i64 = i64::MIN;
            let mut found: bool = false;
            let mut i2: usize = 0;
            while i2 < a.len()
                invariant sec_inv(a, m, s, found, i2), full_max(a, m),
                decreases a.len() - i2,
            {
                if a[i2] < m && (!found || a[i2] > s) {
                    s = a[i2];
                    found = true;
                }
                i2 = i2 + 1;
            }
            s
        }
    }
}

#[summary("array tasks: rotate_right in place")]
mod tasks {
    spec fn lt_len(a: &[i64], m: usize) -> bool {
        m < a.len()
    }

    spec fn mod_all(n: usize, m: usize) -> bool {
        forall|x: usize| x < n ==> (x < m ==> #[trigger] ((x + n - m) % n) == x + n - m) && (x >= m ==> (x + n - m) % n == x - m)
    }

    spec fn mod_args(n: usize, m: usize) -> bool {
        m < n
    }

    #[effects(pure)]
    #[uses(mod_all, mod_args)]
    fn mod_lemma(n: usize, m: usize) -> ()
        requires mod_args(n, m),
        ensures mod_all(n, m),
    {}

    spec fn rev_inv(a: &[i64], o: &[i64], lo: usize, hi: usize, i: usize, j: usize) -> bool {
        a.len() == o.len() && lo <= i && i <= j && j <= hi && hi <= a.len() && i + j == lo + hi && (forall|x: usize| x < a.len() ==> (lo <= x && x < i || j <= x && x < hi ==> #[trigger] a[x] == o[lo + hi - 1 - x]) && (x < lo || x >= hi || i <= x && x < j ==> a[x] == o[x]))
    }

    spec fn rev_post(a: &[i64], o: &[i64], lo: usize, hi: usize) -> bool {
        a.len() == o.len() && (forall|x: usize| x < a.len() ==> (lo <= x && x < hi ==> #[trigger] a[x] == o[lo + hi - 1 - x]) && (x < lo || x >= hi ==> a[x] == o[x]))
    }

    #[effects(pure)]
    #[uses(rev_inv, rev_post, rng)]
    fn reverse(a: &mut [i64], lo: usize, hi: usize) -> ()
        requires rng(a, lo, hi),
        ensures rev_post(a, old(a), lo, hi),
    {
        let mut i: usize = lo;
        let mut j: usize = hi;
        while i + 1 < j
            invariant rev_inv(a, old(a), lo, hi, i, j),
            decreases j - i,
        {
            let t: i64 = a[i];
            let u: i64 = a[j - 1];
            a[i] = u;
            a[j - 1] = t;
            i = i + 1;
            j = j - 1;
        }
    }

    spec fn rng(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }

    spec fn rot_m(a: &[i64], o: &[i64], m: usize) -> bool {
        a.len() == o.len() && m < a.len() && (forall|x: usize| x < a.len() ==> (x < m ==> #[trigger] a[x] == o[x + a.len() - m]) && (x >= m ==> a[x] == o[x - m]))
    }

    spec fn rot_post(a: &[i64], o: &[i64], k: usize) -> bool {
        a.len() == o.len() && (forall|x: usize| x < a.len() ==> (x < k % a.len() ==> #[trigger] a[x] == o[x + a.len() - k % a.len()]) && (x >= k % a.len() ==> a[x] == o[x - k % a.len()]))
    }

    #[effects(pure)]
    #[uses(lt_len, rev_post, rng, rot_m)]
    fn rotate_m(a: &mut [i64], m: usize) -> ()
        requires lt_len(a, m),
        ensures rot_m(a, old(a), m),
    {
        let n: usize = a.len();
        reverse(a, 0, n);
        reverse(a, 0, m);
        reverse(a, m, n);
    }

    #[effects(pure)]
    #[uses(lt_len, rot_m, rot_post)]
    fn rotate_right(a: &mut [i64], k: usize) -> ()
        ensures rot_post(a, old(a), k),
    {
        let n: usize = a.len();
        if n > 0 {
            let m: usize = k % n;
            rotate_m(a, m);
        }
    }
}

#[summary("sorted slice dedup")]
mod tasks {
    spec fn count_distinct(o: &[i64], i: usize) -> usize
        decreases i,
    {
        if i > o.len() || i == 0 {
            0
        } else if i == 1 {
            1
        } else if o[i - 1] != o[i - 2] {
            count_distinct(o, i - 1) + 1
        } else {
            count_distinct(o, i - 1)
        }
    }

    #[effects(pure)]
    #[uses(count_distinct, last_is, members, present, result_ok, same_prefix_forall, sorted, strict_prefix, tail_same, tail_zero)]
    fn dedup_sorted(a: &mut [i64]) -> (r: usize)
        requires sorted(a),
        ensures result_ok(a, old(a), r),
    {
        let n: usize = a.len();
        let mut i: usize = 0;
        let mut w: usize = 0;
        while i < n
            invariant i <= n, w <= i, n == a.len(), n == old(a).len(), sorted(old(a)), strict_prefix(a, w), w == count_distinct(old(a), i), members(a, old(a), i, w), tail_same(a, old(a), i), last_is(a, old(a), i, w),
            decreases n - i,
        {
            if i == 0 || a[i] != a[w - 1] {
                a[w] = a[i];
                w = w + 1;
            }
            i = i + 1;
        }
        zero_tail(a, w);
        w
    }

    spec fn last_is(a: &[i64], o: &[i64], i: usize, w: usize) -> bool {
        i == 0 || 1 <= w && w <= a.len() && i <= o.len() && a[w - 1] == o[i - 1]
    }

    spec fn members(a: &[i64], o: &[i64], i: usize, w: usize) -> bool {
        forall|m: usize| m < w && w <= a.len() ==> present(o, i, #[trigger] a[m])
    }

    spec fn present(a: &[i64], w: usize, v: i64) -> bool {
        exists|m: usize| m < w && w <= a.len() && #[trigger] a[m] == v
    }

    spec fn result_ok(a: &[i64], o: &[i64], r: usize) -> bool {
        a.len() == o.len() && r <= a.len() && strict_prefix(a, r) && members(a, o, o.len(), r) && r == count_distinct(o, o.len()) && tail_zero(a, r)
    }

    spec fn same_prefix_forall(a: &[i64], o: &[i64], w: usize) -> bool {
        forall|k: usize| k < w && w <= a.len() && a.len() == o.len() ==> a[k] == #[trigger] o[k]
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i < j && j < a.len() ==> #[trigger] a[i] <= #[trigger] a[j]
    }

    spec fn strict_prefix(a: &[i64], w: usize) -> bool {
        forall|p: usize, q: usize| p < q && q < w && w <= a.len() ==> #[trigger] a[p] < #[trigger] a[q]
    }

    spec fn tail_same(a: &[i64], o: &[i64], i: usize) -> bool {
