            i = i + 1;
        }
        ()
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|k: usize, l: usize| k <= l && l < a.len() ==> #[trigger] a[k] <= #[trigger] a[l]
    }

    spec fn sorted_prefix(a: &[i64], i: usize) -> bool {
        forall|k: usize, l: usize| k <= l && l < i && i <= a.len() ==> #[trigger] a[k] <= #[trigger] a[l]
    }

    #[effects(pure)]
    #[uses(count, fact, ind, lt, lt_len, perm, same_len, swapped)]
    fn swap(a: &mut [i64], i: usize, j: usize) -> ()
        requires lt(i, j), lt_len(j, a),
        ensures same_len(old(a), a), perm(old(a), a), swapped(old(a), a, i, j),
    {
        let x: i64 = a[i];
        let y: i64 = a[j];
        a[i] = y;
        a[j] = x;
        let mut n: usize = 0;
        while n < a.len()
            invariant fact(old(a), a, i, j, n), swapped(old(a), a, i, j),
            decreases a.len() - n,
        {
            n = n + 1;
        }
        ()
    }

    spec fn swapped(a: &[i64], b: &[i64], i: usize, j: usize) -> bool {
        a.len() == b.len() && i < j && j < a.len() && b[i] == a[j] && b[j] == a[i] && (forall|k: usize| k < a.len() && k != i && k != j ==> #[trigger] b[k] == a[k])
    }
}

#[summary("pow_mod: modular exponentiation")]
mod tasks {
    spec fn add_mult(x: i64, k: i64, m: i64) -> bool {
        (x + m * k) % m == x % m
    }

    #[effects(pure)]
    #[uses(add_mult, m_ok, nonneg)]
    fn lem_add_mult(x: i64, k: i64, m: i64) -> ()
        requires m_ok(m), nonneg(k),
        ensures add_mult(x, k, m),
        decreases k,
    {
        if k > 0 {
            lem_add_mult(x, k - 1, m);
        }
    }

    #[effects(pure)]
    #[uses(add_mult, m_ok, mod_mul, nonneg)]
    fn lem_mod_mul(a: i64, b: i64, m: i64) -> ()
        requires m_ok(m), nonneg(a), nonneg(b),
        ensures mod_mul(a, b, m),
    {
        lem_add_mult(a % m * b, a / m * b, m);
    }

    #[effects(pure)]
    #[uses(add_mult, m_ok, mod_mul2, nonneg)]
    fn lem_mod_mul2(a: i64, b: i64, m: i64) -> ()
        requires m_ok(m), nonneg(a), nonneg(b),
        ensures mod_mul2(a, b, m),
    {
        lem_add_mult(a * (b % m), a * (b / m), m);
    }

    spec fn m_ok(m: i64) -> bool {
        1 <= m && m <= 3000000000
    }

    spec fn mod_mul(a: i64, b: i64, m: i64) -> bool {
        a % m * b % m == a * b % m
    }

    spec fn mod_mul2(a: i64, b: i64, m: i64) -> bool {
        a * (b % m) % m == a * b % m
    }

    spec fn nonneg(a: i64) -> bool {
        0 <= a
    }
}
